export type TemplateKind = 'AUTO' | 'MANUAL'
export type MessageChannel = 'kakao' | 'email'

export type MessageTemplate = {
  id: string
  channel: MessageChannel
  kind: TemplateKind
  title: string
  stage: string
  source: string
  locale: string
  body: string
  variables?: string
  buttons?: string
  buttonLink?: string
  sendAt?: string
  conditions?: string
  note?: string
}

export const TEMPLATE_KIND_LABEL: Record<TemplateKind, string> = {
  AUTO: '자동',
  MANUAL: '수동',
}

