    body: "#{고객명}님, 접수하신 제품이 반송됩니다.\n\n이번 서비스는 고객님 요청 또는 결제 미확인으로 종료되어\n제품을 반송해드립니다. 다시 진행을 원하시면 언제든 재접수해주세요.\n\n입고된 제품은 안전하게 포장해 수령 스토어로 보내드립니다.\n스토어에 도착하면 다시 안내드릴게요. 안내를 받으신 뒤 방문해주세요.\n\n티켓번호 #{티켓번호}\n제품명\t#{제품명}\n사유\t#{수리내용}\n스토어\t#{매장명} / #{매장전화번호}",
