    body: "안녕하세요 #{고객명} 고객님,\n제품 이용에 불편 드려 죄송합니다.\n\n제품에 장착하신 처방(도수) 렌즈는 고객님의 개인 소유물로 분류되어,\n당사의 공식 보상 기준에는 포함되지 않습니다.\n\n다만, 고객님의 불편을 조금이나마 덜어드리고자 예외적으로 렌즈 비용의 일부를 지원해 드리는 보상 방안을 마련하였습니다. 아래 안내해 드리는 내용을 확인하신 후 서류와 함께 회신해 주시기 바랍니다.\n\n■ 보상 방식\n신규 또는 기존 렌즈 비용 확인 후 최대 10만원 현금 지원\n\n■ 필수 서류 (5가지)\n① 의료비 영수증(안경원 발급)\n② 결제 영수증\n③ 개인 정보(여권 또는 신분증)\n④ SWIFT CODE\n⑤ 계좌 사본\n\n■ 접수처\n공식 홈페이지 [라이브 챗] 또는 [이메일 문의]로 서류 첨부 회신",
    variables: "#{고객명}",
    buttons: "▶ 회신하기",
    buttonLink: "회신하기 누르면 Web 문의하기로 이동",
    sendAt: "수동",
