    title: "DIAG_06 [판정] 복원수리_유상",
    stage: "판정",
    source: "US",
    locale: "KO",
    body: "#{고객명}님, 점검을 완료했습니다.\n아래 내용 확인 후 결제를 진행해 주세요.\n결제 확인 후 절차가 진행됩니다.\n\n※ 복원 수리 참고사항을 확인해 주세요.\n· 기존 도금 제거 후 재도금되어, 템플 안쪽 각인이 지워질 수 있습니다.\n· 재도금 시 기존 메탈 색상과 차이가 발생할 수 있습니다.\n· 메탈 손상 부위는 도금 후 표면이 고르지 않을 수 있습니다.\n· 용접 부위에 자국이 남거나 반대쪽과 차이가 있을 수 있으며, 표면 질감이 달라질 수 있습니다.\n· 제품 구조나 디자인에 따라 도금 및 용접이 불가능하거나 제한될 수 있습니다.\n\n티켓번호 #{티켓번호}\n제품명\t#{제품명}\n서비스 유형\t#{수리내용}\n비용\t#{수리비용}\n출고 예정일 : \t결제완료 후 영업일 기준 약 40일 소요",
