    stage: "판정",
    source: "US",
    locale: "KO",
    body: "#{고객명}님, 점검 결과를 안내해 드립니다.\n\n접수하신 모델은 수리 부품이 소진되어 동일한 모델로 수리가 어려운 상태입니다.\n\n보증 기간 내 수리가 불가한 경우 다른 제품으로 교환해드리는 서비스를 제공합니다.\n아래 내용 확인 후 진행을 원하시면, 1주일 이내에 희망 모델을 회신해 주세요.\n\n※ 타제품 교환 안내 사항을 확인해 주세요.\n· 교환 제품은 기존 제품의 가격과 관계없이 선택하실 수 있습니다.\n  (단, 콜라보레이션 및 일부 컬렉션 제품 제외)\n· 타제품으로 교환 시 새 제품의 구성품(케이스 등)은 별도로 제공되지 않습니다.\n· 교환 제품의 품질 및 서비스 보증 기간은 기존 제품의 잔여 보증 기간으로 적용됩니다.\n· 교환 제품은 프로덕트 서비스 팀에서 발송합니다.\n\n티켓번호 #{티켓번호}\n제품명\t#{제품명}\n비용\t#{수리비용} (기존 수리 비용 적용)",
