    body: "안녕하세요 #{고객명} 고객님,\n제품 이용에 불편 드려 죄송합니다.\n\n수리 과정에서 고객님의 렌즈가 손상되어 깊이 사과드립니다.\n\n저희 RX 팀에서 고객님의 도수에 맞는 렌즈를 새로 제작하여\n수리된 제품과 함께 발송해 드릴 예정입니다.\n\n렌즈 제작을 위해 아래 서류를 회신해 주시기 바랍니다.\n\n■ 필수 서류\n· 도수 처방전 (안경원 또는 안과 발급)\n\n서류 확인 후 제작이 시작되며, 완료 시 다시 안내드릴게요.\n궁금하신 점이 있으시면 언제든지 문의해 주세요.",
