    body: "안녕하세요 #{고객명} 고객님,\n접수가 완료되었어요.\n\n접수일로부터 14일 이내에 아래 주소로 제품을 발송해 주세요.\n기한 내 입고되지 않으면 접수가 자동으로 취소됩니다.\n\n📦 발송 주소\n〒150-0002\n東京都渋谷区渋谷1-3-3 ヒューリック青山第二ビル 6階\n株式会社IICOMBINED JAPAN\n발송 시 박스 안에 티켓 번호와 성함을 동봉해 주세요.\n\n■ 확인사항\n•  별도로 제작한 렌즈(도수·블루라이트 렌즈 등)는 분리 후 본체만 발송해주세요.\n   분리하지 않은 렌즈는 손상 시 보상이 어려운 점 참고해주세요.\n•  보증카드·안경 케이스·안경 닦이 등 구성품은 동봉하지 말아주세요.\n   분실 방지를 위해 따로 보관해주시고, 함께 보내신 구성품은 별도로 반송될 수 있어요.\n\n티켓번호 #{티켓번호}\n제품명\t#{제품명}\n수거 방법 : \t직접 발송",
